344	// publish so it converges on the hosted open set: an entry the ledger says was
345	// shared but the hosted set no longer carries was settled by another member and
346	// is dropped; entries still hosted-open stay; entries never yet shared stay for
347	// the next publish. The ledger is then rewritten to the hosted set, which by
348	// definition holds every currently shared proposal.
349	// readSharedFactHead pulls the shared fact-set head and parses it. An absent head
350	// yields no records and no error — a branch nobody has synced yet is a normal state,
351	// not a failure. Only a transport fault or unparseable content is an error, and the
352	// caller degrades rather than failing a sync whose head-advance already succeeded.
353	func readSharedFactHead(ctx context.Context, srv factsync.Server, repoID, branch string) ([]factRecord, error) {
354		_, plaintext, found, err := srv.Current(ctx, repoID, branch)
355		if err != nil {
356			return nil, err
357		}
358		if !found || len(plaintext) == 0 {
359			return nil, nil
360		}
361		parsed, err := factmerge.ParseNDJSON(bytes.NewReader(plaintext))
362		if err != nil {
363			return nil, fmt.Errorf("parse shared memory head: %w", err)
364		}
365		// The head is written by every member with push access. Re-derive each
366		// record's content id before any of it reaches local state: this read feeds
367		// proposal reconciliation, which supersedes and removes LOCAL facts by id.
368		if err := factmerge.VerifyIdentities(parsed); err != nil {
369			return nil, fmt.Errorf("shared memory head for %s/%s is not trustworthy: %w", repoID, branch, err)
370		}
371		return parsed, nil
372	}
