374	// proposalStillOpenAgainst reports whether p is a live conflict against the shared
375	// head — both of its facts still present, and the target not already superseded by
376	// the candidate. A settled or stale proposal fails this and must not be republished.
377	//
378	// This is what makes settlement stick ACROSS CLONES: the shared-proposal ledger is
379	// per-checkout, so a second clone of the same member has no record of what was
380	// published and would resurrect conflicts the team already resolved. The head is
381	// the same for every clone.
382	func proposalStillOpenAgainst(hostedFacts []factRecord, p factProposal) bool {
383		ci := indexOfFact(hostedFacts, p.CandidateID)
384		ti := indexOfFact(hostedFacts, p.TargetID)
385		if ci < 0 || ti < 0 {
386			return false // one side is gone: merged away, retracted, or GC'd
387		}
388		if hostedFacts[ti].Status == factStatusSuperseded && hostedFacts[ti].SupersededBy == p.CandidateID {
389			return false // already superseded exactly as this proposal asked
390		}
391		if hostedFacts[ci].Status == factStatusSuperseded && hostedFacts[ci].SupersededBy == p.TargetID {
392			return false // settled the other way round
393		}
394		return true
395	}
