397	// settledHostedAsAccept reports whether the shared fact-set head shows p as
398	// ACCEPTED. A settled proposal carries no decision field, so the decision is
399	// derived from the effect ApplyProposal would have left on the head:
400	//
401	//	merge     accept removes the candidate and keeps the target
402	//	supersede accept flips the target to superseded, pointing at the candidate
403	//
404	// Anything else (both ids still present and merely unlinked, or a fact that has
405	// since moved on) reads as a reject: reject changes no fact status, so mirroring
406	// it locally is limited to clearing the conflict cross-link.
407	func settledHostedAsAccept(hostedFacts []factRecord, p factProposal) bool {
408		ci := indexOfFact(hostedFacts, p.CandidateID)
409		ti := indexOfFact(hostedFacts, p.TargetID)
410		if p.Action == factActionMerge {
411			return ci < 0 && ti >= 0
412		}
413		return ti >= 0 && hostedFacts[ti].Status == factStatusSuperseded && hostedFacts[ti].SupersededBy == p.CandidateID
414	}
