419	//
420	// Without this the settlement does not stick: the losing member's local copy
421	// still holds the retired fact, and the next sync's keep-both Promote re-adds it
422	// and re-raises the same conflict under a fresh id — an unresolvable loop for
423	// whichever member lost the merge.
424	func applySettlementLocally(facts []factRecord, p factProposal, accepted bool, now time.Time) ([]factRecord, bool) {
425		if !accepted {
426			// Reject: clear the local cross-link so the pair stops reading as
427			// conflicting. With either side absent there is no link to clear, so report
428			// no change rather than rewriting the fact store and bumping the source
429			// manifest for nothing.
430			if indexOfFact(facts, p.CandidateID) < 0 || indexOfFact(facts, p.TargetID) < 0 {
431				return facts, false
432			}
433			return rejectProposal(facts, p), true
434		}
435		updated, err := applyProposal(facts, p, now)
436		if err != nil {
437			// The local copy no longer holds both sides (already retracted, GC'd, or
438			// settled here). The hosted decision is still authoritative and already
439			// recorded; there is nothing left locally to reconcile.
440			return facts, false
441		}
442		return updated, true
443	}
