445	func reconcileLocalProposalQueue(brainDir, branch string, hosted []factsync.OpenProposal, hostedFacts []factRecord, now time.Time) error {
446		hostedIDs := make(map[string]struct{}, len(hosted))
447		for _, p := range hosted {
448			hostedIDs[p.ID] = struct{}{}
449		}
450		return withBrainWriteLock(brainDir, func() error {
451			ledger, err := loadSharedProposalLedger(brainDir, branch)
452			if err != nil {
453				return err
454			}
455			current, err := loadFactProposals(brainDir, branch)
456			if err != nil {
457				return err
458			}
459			// A settled entry may only be pruned once its settlement has been mirrored
460			// into local facts. Mirroring needs the shared head, so with no head to read
461			// the entry STAYS QUEUED and the next sync retries: pruning it here would
462			// drop the only record of what still needs mirroring, leaving the retired
463			// fact active locally with nothing left to reconcile it against — the exact
464			// defect this function exists to close, reintroduced through the back door.
465			canMirror := len(hostedFacts) > 0
466			next := make([]factProposal, 0, len(current))
467			settled := make([]factProposal, 0, len(current))
468			for _, p := range current {
469				id := factsync.ProposalID(p)
470				_, stillOpen := hostedIDs[id]
471				_, wasShared := ledger[id]
472				if stillOpen || !wasShared {
473					next = append(next, p)
474					continue
475				}
476				if !canMirror {
477					next = append(next, p) // settled, but keep it until it can be mirrored
478					continue
479				}
480				// Shared once, gone from the hosted set: another member settled it.
481				settled = append(settled, p)
482			}
483			// Mirror BEFORE dropping the queue entries, so a crash between the two
484			// writes leaves the entries in place and the next sync redoes the mirror
485			// (idempotent) rather than losing it.
486			if len(settled) > 0 {
487				facts, factsErr := loadFacts(brainDir, branch)
488				if factsErr != nil {
489					return factsErr
490				}
491				changed := false
492				for _, p := range settled {
493					updated, did := applySettlementLocally(facts, p, settledHostedAsAccept(hostedFacts, p), now)
494					facts = updated
495					changed = changed || did
496				}
497				if changed {
498					if err := writeFacts(brainDir, branch, facts); err != nil {
499						return err
500					}
501					if err := updateFactSourceManifestLocked(brainDir, now); err != nil {
502						return err
503					}
504				}
505			}
506			// Queue first, ledger second: a crash between the writes then leaves a
507			// stale EXTRA ledger id (harmless — it only suppresses a republish),
508			// whereas the reverse order would mark still-queued settled proposals
509			// as never-shared and resurrect them on the next sync.
510			if len(next) != len(current) {
511				if err := writeFactProposals(brainDir, branch, next); err != nil {
512					return err
513				}
514			}
515			merged := make(map[string]struct{}, len(hostedIDs)+len(ledger))
516			for id := range hostedIDs {
517				merged[id] = struct{}{}
518			}
519			for id := range ledger {
520				merged[id] = struct{}{}
521			}
522			return writeSharedProposalLedger(brainDir, branch, merged)
523		})
524	}
