526	// publishRaisedProposals shares a sync's raised conflicts through the backend's open
527	// proposal queue when it has one. A backend that only implements the fact-set head
528	// seam (internal/factgitmeta's local store) is a no-op, so the default local flow is
529	// unchanged and never reaches the network.
530	func publishRaisedProposals(ctx context.Context, srv factsync.Server, repoID, branch string, raised []factProposal) (factsync.PublishResult, error) {
531		if len(raised) == 0 {
532			return factsync.PublishResult{}, nil
533		}
534		transport, ok := srv.(factsync.ProposalTransport)
535		if !ok {
536			return factsync.PublishResult{}, nil
537		}
538		return factsync.PublishRaised(ctx, transport, repoID, branch, raised)
539	}
