553	// buildFactsSyncBackend constructs the selected Server, returning it, the repoID
554	// to thread through Sync, and a human label for output. The local-gitmeta path
555	// is keyed by the repo storage key; the http path mirrors publish's opt-in gates
556	// and flag/env resolution.
557	func buildFactsSyncBackend(ctx context.Context, opts Options, backend string, storage repoStorage, repoDir string, syncOpts factsSyncOptions) (factsync.Server, string, string, error) {
558		switch backend {
559		case factsBackendLocalGitmeta:
560			gitDir, err := gitmetaDirForKey(opts.Env, storage.Key)
561			if err != nil {
562				return nil, "", "", err
563			}
564			b, err := factgitmeta.NewLocalBackend(gitDir, storage.Key, opts.Now)
565			if err != nil {
566				return nil, "", "", err
567			}
568			return b, storage.Key, "local-gitmeta (" + gitDir + ")", nil
569	
570		case factsBackendHTTP:
571			// The master kill switch always wins over the hosted opt-in; the opt-in
572			// itself is the resolved target (mirrors publish).
573			if brainNoEgressMode() {
574				return nil, "", "", fmt.Errorf("no_egress: hosted memory sync is disabled while %s is set; unset it or use --memories-backend=local-gitmeta", noEgressToggleName())
575			}
576			// Flag > env > connected binding; validation (repo-id segment, URL
577			// scheme floor) happens inside, before the backend is built.
578			target, err := resolveManualHostedTarget(ctx, opts, storage.BrainDir, repoDir, "memories sync", syncOpts.repoID, syncOpts.apiURL, syncOpts.token)
579			if err != nil {
580				return nil, "", "", err
581			}
582			return &factsync.HTTPServer{BaseURL: target.baseURL, Token: target.token}, target.repoID, "http (" + strings.TrimRight(target.baseURL, "/") + ")", nil
583	
584		default:
585			return nil, "", "", fmt.Errorf("unknown --memories-backend %q (want %q or %q)", backend, factsBackendLocalGitmeta, factsBackendHTTP)
586		}
587	}
