589	// resolveSyncMemberID derives the member identity stamped on cross-member
590	// proposals: the explicit --member, else the repo's git user.email, else
591	// $USER@<hostname>, else "local". A non-empty id is required (Sync rejects "").
592	func resolveSyncMemberID(ctx context.Context, runner CommandRunner, repoDir, override string) string {
593		if v := strings.TrimSpace(override); v != "" {
594			return v
595		}
596		if email, err := gitScalar(ctx, runner, repoDir, "config", "--get", "user.email"); err == nil {
597			if e := strings.TrimSpace(email); e != "" {
598				return e
599			}
600		}
601		if u := strings.TrimSpace(os.Getenv("USER")); u != "" {
602			if host, err := os.Hostname(); err == nil && host != "" {
603				return u + "@" + host
604			}
605			return u
606		}
607		return "local"
608	}
