610	// gitmetaDirForKey resolves the local git-meta store path for a repo key
611	// (<cache>/brain/<key>/gitmeta.git), mirroring brainDirForKey's key handling but
612	// rooted in the plugin CACHE tree (the store is a local, rebuildable sync
613	// staging area, not authoritative brain data).
614	func gitmetaDirForKey(env EntireEnv, key string) (string, error) {
615		if first, _, _ := strings.Cut(key, "/"); first == workspaceDirName {
616			return "", fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
617		}
618		dirs, err := resolvePluginDirs(env)
619		if err != nil {
620			return "", err
621		}
622		root := filepath.Join(dirs.Cache, "brain")
623		if err := rejectBrainRootPathSymlinks(root, filepath.FromSlash(key)); err != nil {
624			return "", err
625		}
626		return filepath.Join(root, filepath.FromSlash(key), "gitmeta.git"), nil
627	}
