17	// hostEntireBinary is the host CLI the plugin shells out to; PATH comes from
18	// the caller's environment (the daemon plist bakes PATH at install time).
19	const hostEntireBinary = "entire"
20	
21	const (
22		// hostedUpsertChunk stays well under brainstore's 5000-record batch cap
23		// and its 32 MiB body cap.
24		hostedUpsertChunk = 1000
25		// hostedFeedPageSize is brainstore's page-size ceiling.
26		hostedFeedPageSize = 100
27		// maxHostedFeedPages bounds one pull so the never-fails path cannot spin
28		// on a pathological feed. ponytail: a delta larger than 20k records
29		// finishes on the next trigger — the cursor persists either way.
30		maxHostedFeedPages = 200
31	)
32	
33	// hostedSyncOutcome reports what one hostedFactsSyncAndPull run did.
34	type hostedSyncOutcome struct {
35		Attempted     bool
36		PullSucceeded bool
37	}
38	
39	// hostedFactsSyncAndPull closes the hosted-memory loop for one branch on the
40	// per-fact wire (COR-2126): batch-upsert this machine's branch store to
41	// brainstore, pull the repo-wide delta feed into the repo-level cache, and
42	// rebuild the branch store as the pull filter's output plus this machine's
43	// own facts the feed has not seen. No CAS, no branch heads, no proposals —
44	// per-fact storage keeps conflicting facts side by side and resolution stays
45	// deferred to the async pipeline.
46	//
47	// It is a NEVER-FAILS step: every gated or soft failure is one stderr line and
48	// a nil return, because its callers (daemon tick, session-end hook, connect)
49	// must not fail on hosted outages. The error return exists for programming
50	// errors only.
51	//
52	// Gate order is fixed: (1) the local-only kill switch always wins; (2) a
53	// recorded opt-out (`entire brain disconnect`) stops sync until `connect`
54	// clears it; (3) the repo binding is the consent AND the connection state —
55	// only `entire brain connect` (or the future onboarding flow) writes it, so an
56	// absent binding means local-only, silently, every run. Background triggers
57	// never connect a repo. (4) apiurl.Validate before any client exists. A fresh
58	// token is minted per call via the host CLI's own login and held only in
59	// memory.
60	//
61	// The outcome reports what actually happened: Attempted is whether the gates
62	// passed and the server was contacted (callers that log success must not
63	// report a gated no-op as a sync that ran); PullSucceeded is whether the pull
64	// half completed — the half that proves the exchange (the per-branch marker
65	// keys off it). Callers that promise a sync to the user (connect) key their
66	// report off PullSucceeded; background callers keep ignoring it.
67	func hostedFactsSyncAndPull(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage, branch string) (hostedSyncOutcome, error) {
68		if brainNoEgressMode() {
69			return hostedSyncOutcome{}, nil
70		}
71		binding, present, err := readHostedRepoBinding(storage.BrainDir)
72		if err != nil {
73			// NO unreadable binding may fall through to auto-connect: the file may
74			// hide a recorded opt-out (privacy) or a custom target, and neither
75			// survives a rewrite. Skip loudly; the remedy is an explicit
76			// `entire brain connect`.
77			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
78			return hostedSyncOutcome{}, nil
79		}
80		if !present || binding.OptedOut {
81			return hostedSyncOutcome{}, nil
82		}
83		baseURL, err := apiurl.Validate(binding.BaseURL)
84		if err != nil {
85			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
86			return hostedSyncOutcome{}, nil
87		}
88		token, err := mintHostedToken(ctx, opts.Runner, repoDir, hostEntireBinary)
89		if err != nil {
90			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
91			return hostedSyncOutcome{}, nil
92		}
93		srv := &factsync.HTTPServer{BaseURL: baseURL, Token: token}
94	
95		pushed, counts := pushHostedFacts(ctx, errW, storage, srv, binding.RepoID, branch)
96		kept, total, manifestErr, pullErr := pullHostedFacts(ctx, opts, repoDir, storage, srv, binding.RepoID, baseURL, token, branch)
97		if pullErr != nil {
98			fmt.Fprintf(errW, "hosted sync: branch %s pull failed (local brain unaffected): %v\n", branch, pullErr)
99			return hostedSyncOutcome{Attempted: true}, nil
100		}
101		if pushed {
102			// The per-branch marker records that this branch completed a sync
103			// against this target; the blind-spot note keys off its absence. It
104			// needs BOTH halves: a pull-only run leaves it unwritten, and so does
105			// a failed pull — the empty-store push "succeeds" without contacting
106			// the server, so the pull is what proves the exchange happened.
107			if err := writeHostedFactsBinding(storage.BrainDir, branch, binding.RepoID, baseURL); err != nil {
108				fmt.Fprintf(errW, "hosted sync: record hosted target: %v\n", err)
109			}
110		}
111		if manifestErr != nil {
112			fmt.Fprintf(errW, "hosted sync: facts updated, but the source manifest could not be refreshed: %v\n", manifestErr)
113		}
114		fmt.Fprintf(errW, "hosted sync: branch %s pushed added=%d changed=%d unchanged=%d; feed facts=%d kept=%d\n",
115			branch, counts.Added, counts.Changed, counts.Unchanged, total, kept)
116		return hostedSyncOutcome{Attempted: true, PullSucceeded: true}, nil
117	}
118	
119	// pushHostedFacts batch-upserts the branch store. Idempotent server-side, so
120	// every trigger can fire it without coordination. Any failure degrades to
121	// pull-only: one stderr line, pushed=false, and the caller skips the synced
122	// marker so the blind-spot note keeps firing.
123	func pushHostedFacts(ctx context.Context, errW io.Writer, storage repoStorage, srv *factsync.HTTPServer, repoID, branch string) (bool, factsync.UpsertCounts) {
124		facts, err := loadFacts(storage.BrainDir, branch)
125		if err != nil {
126			fmt.Fprintf(errW, "hosted sync: branch %s publish failed (local brain unaffected): %v; pull-only\n", branch, err)
127			return false, factsync.UpsertCounts{}
128		}
129		if len(facts) == 0 {
130			// Nothing to publish counts as a successful (empty) publish; the
131			// server rejects an empty body, so don't send one.
132			return true, factsync.UpsertCounts{}
133		}
134		// Redact local-only provenance coordinates before these facts leave, and
135		// verify this member's own facts BEFORE publishing them — the server
136		// rejects a whole batch for one malformed record, so the check runs here,
137		// per record: one corrupted line must not hold the rest of the store
138		// hostage. Unverifiable records stay home with a note; everything else
139		// uploads.
140		egress := factsync.SanitizeForEgress(facts)
141		publishable := egress[:0]
142		skipped := 0
143		for _, rec := range egress {
144			if err := factmerge.VerifyIdentity(rec); err != nil {
145				skipped++
146				continue
147			}
148			publishable = append(publishable, rec)
149		}
150		egress = publishable
151		if skipped > 0 {
152			fmt.Fprintf(errW, "hosted sync: branch %s: skipped %d unpublishable record(s) whose content id does not re-derive (kept locally, not uploaded)\n", branch, skipped)
153		}
154		if len(egress) == 0 {
155			// Everything was unpublishable: nothing was shared, so this is a
156			// failed publish, not a vacuous success — the branch must not be
157			// marked as synced.
158			fmt.Fprintf(errW, "hosted sync: branch %s publish failed (local brain unaffected): no publishable records; pull-only\n", branch)
159			return false, factsync.UpsertCounts{}
160		}
161		var total factsync.UpsertCounts
162		for start := 0; start < len(egress); start += hostedUpsertChunk {
163			end := min(start+hostedUpsertChunk, len(egress))
164			var buf bytes.Buffer
165			if err := factmerge.WriteNDJSON(&buf, egress[start:end]); err != nil {
166				fmt.Fprintf(errW, "hosted sync: branch %s publish failed (local brain unaffected): %v; pull-only\n", branch, err)
167				return false, factsync.UpsertCounts{}
168			}
169			counts, err := srv.UpsertFacts(ctx, repoID, buf.Bytes())
170			if err != nil {
171				fmt.Fprintf(errW, "hosted sync: branch %s publish failed (local brain unaffected): %v; pull-only\n", branch, err)
172				return false, factsync.UpsertCounts{}
173			}
174			total.Added += counts.Added
175			total.Changed += counts.Changed
176			total.Unchanged += counts.Unchanged
177		}
178		return true, total
179	}
