16	// This file is the per-fact wire (COR-2126): brainstore's idempotent batch
17	// upsert and repo-wide delta feed, published by the cell gateway under the
18	// same /api/v1/repos/{id}/brain/* namespace as the branch-head endpoints
19	// (verified live: the bare path 404s, /api/v1/brain/v1/health answers with
20	// brainstore's health body).
21	
22	// ErrInvalidPageToken is returned when the feed rejects the stored cursor
23	// (400 with a token sent) — the server's keyset epoch moved. The caller
24	// resets its cursor and cache and refetches from the start.
25	var ErrInvalidPageToken = errors.New("factsync: hosted feed rejected the page token")
26	
27	// UpsertCounts is the facts upsert response: how the batch landed.
28	type UpsertCounts struct {
29		Added     int `json:"added"`
30		Changed   int `json:"changed"`
31		Unchanged int `json:"unchanged"`
32	}
33	
34	// FeedItem is one delta-feed entry: the wire record (entire-brain factmerge
35	// encoding, snake_case) wrapped in the server-owned camelCase envelope.
36	type FeedItem struct {
37		Record          factmerge.Record `json:"record"`
38		TrailID         string           `json:"trailId"`
39		CreatedBy       string           `json:"createdBy"`
40		CreatedByHandle string           `json:"createdByHandle"`
41		UpdatedAt       string           `json:"updatedAt"`
42	}
43	
44	// FeedPage is one page of the delta feed. Every non-empty page carries the
45	// resume token positioned after its last item; only an empty page is
46	// terminal-for-now (nil token).
47	type FeedPage struct {
48		Items         []FeedItem `json:"items"`
49		NextPageToken *string    `json:"nextPageToken"`
50	}
51	
52	// brainPath builds the per-fact route base on repoBasePath, the package's
53	// single point where a repo id becomes part of a request target.
54	func brainPath(repoID string) (string, error) {
55		base, err := repoBasePath(repoID)
56		if err != nil {
57			return "", err
58		}
59		return base + "/brain", nil
60	}
61	
62	// UpsertFacts posts one NDJSON batch to the idempotent per-fact upsert. The
63	// caller chunks to the server's batch cap and verifies identities first —
64	// one bad record rejects the whole batch server-side.
65	func (h *HTTPServer) UpsertFacts(ctx context.Context, repoID string, ndjson []byte) (UpsertCounts, error) {
66		base, err := brainPath(repoID)
67		if err != nil {
68			return UpsertCounts{}, err
69		}
70		// POST on the facts collection is the batch upsert (COR-2212 replaced the
71		// facts:upsert colon path); requires a brainstore that serves it.
72		req, err := h.newRequest(ctx, http.MethodPost, base+"/facts", bytes.NewReader(ndjson))
73		if err != nil {
74			return UpsertCounts{}, err
75		}
76		req.Header.Set("Content-Type", "application/x-ndjson")
77		resp, err := h.do(req)
78		if err != nil {
79			return UpsertCounts{}, fmt.Errorf("factsync: POST facts upsert %s: %w", repoID, err)
80		}
81		defer resp.Body.Close()
82		if resp.StatusCode != http.StatusOK {
83			return UpsertCounts{}, fmt.Errorf("factsync: POST facts upsert %s: unexpected status %s%s", repoID, resp.Status, h.detail(resp))
84		}
85		var counts UpsertCounts
86		if err := httpx.DecodeJSONBody(resp, &counts); err != nil {
87			return UpsertCounts{}, fmt.Errorf("factsync: decode facts upsert %s: %w", repoID, err)
88		}
89		return counts, nil
90	}
91	
92	// FactsFeedPage reads one page of the repo-wide delta feed. pageToken ""
93	// starts from the beginning; pageSize is clamped server-side.
94	func (h *HTTPServer) FactsFeedPage(ctx context.Context, repoID, pageToken string, pageSize int) (FeedPage, error) {
95		base, err := brainPath(repoID)
96		if err != nil {
97			return FeedPage{}, err
98		}
99		query := url.Values{}
100		if pageToken != "" {
101			query.Set("pageToken", pageToken)
102		}
103		if pageSize > 0 {
104			query.Set("pageSize", strconv.Itoa(pageSize))
105		}
106		path := base + "/facts"
107		if encoded := query.Encode(); encoded != "" {
108			path += "?" + encoded
109		}
110		req, err := h.newRequest(ctx, http.MethodGet, path, nil)
111		if err != nil {
112			return FeedPage{}, err
113		}
114		resp, err := h.do(req)
115		if err != nil {
116			return FeedPage{}, fmt.Errorf("factsync: GET facts feed %s: %w", repoID, err)
117		}
118		defer resp.Body.Close()
119		switch {
120		case resp.StatusCode == http.StatusOK:
121		case resp.StatusCode == http.StatusBadRequest && pageToken != "":
122			return FeedPage{}, fmt.Errorf("%w%s", ErrInvalidPageToken, h.detail(resp))
123		default:
124			return FeedPage{}, fmt.Errorf("factsync: GET facts feed %s: unexpected status %s%s", repoID, resp.Status, h.detail(resp))
125		}
126		var page FeedPage
127		if err := httpx.DecodeJSONBody(resp, &page); err != nil {
128			return FeedPage{}, fmt.Errorf("factsync: decode facts feed %s: %w", repoID, err)
129		}
130		return page, nil
131	}
