36	// commandSubcommandNames lists a group node's verbs in registration order, so
37	// the "requires a subcommand" error names exactly what exists rather than a
38	// hand-maintained copy that drifts the next time a verb is added.
39	func commandSubcommandNames(cmd *cobra.Command) []string {
40		names := make([]string, 0, len(cmd.Commands()))
41		for _, sub := range cmd.Commands() {
42			if sub.Hidden || sub.Name() == "help" {
43				continue
44			}
45			names = append(names, sub.Name())
46		}
47		return names
48	}
