166	// hostedProposalTarget is the resolved hosted target for one `facts proposals` run.
167	type hostedProposalTarget struct {
168		client  *hostedbrain.Client
169		repoID  string
170		branch  string
171		baseURL string
172	}
173	
174	// resolveHostedProposalTarget enforces the egress gates and resolves the hosted
175	// target. It performs NO network call, so every refusal below is egress-free.
176	func resolveHostedProposalTarget(ctx context.Context, opts Options, pOpts factsProposalsOptions) (hostedProposalTarget, error) {
177		// The master kill switch always wins over the hosted opt-in; the opt-in
178		// itself is the resolved target (mirrors publish).
179		if brainNoEgressMode() {
180			return hostedProposalTarget{}, fmt.Errorf("no_egress: hosted proposal review is disabled while %s is set; unset it, or use 'memories review' for this member's local proposals", noEgressToggleName())
181		}
182	
183		// The binding default needs the repo's brain dir; this surface also works
184		// from a checkout without one, so a failed resolution only disables the
185		// default — explicit flags still carry the command.
186		var brainDir, repoDir string
187		if dir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil)); err == nil && local {
188			repoDir = dir
189			if storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, dir); err == nil {
190				brainDir = storage.BrainDir
191			}
192		}
193		target, err := resolveManualHostedTarget(ctx, opts, brainDir, repoDir, "memories proposals", pOpts.repoID, pOpts.apiURL, pOpts.token)
194		if err != nil {
195			return hostedProposalTarget{}, err
196		}
197	
198		return hostedProposalTarget{
199			client:  &hostedbrain.Client{BaseURL: target.baseURL, Token: target.token},
200			repoID:  target.repoID,
201			branch:  resolveProposalsBranch(ctx, opts, pOpts.branch),
202			baseURL: strings.TrimRight(target.baseURL, "/"),
203		}, nil
204	}
205	
206	// resolveProposalsBranch folds --branch, the repo's current branch, and the default
207	// into the branch whose open set is reviewed. The repo is only consulted for its
208	// branch name — the review target itself is the hosted repo id, so this works from a
209	// checkout without a built brain.
210	func resolveProposalsBranch(ctx context.Context, opts Options, flagVal string) string {
211		if b := strings.TrimSpace(flagVal); b != "" {
212			return b
213		}
214		repoDir := opts.Env.RepoRoot
215		if repoDir == "" {
216			repoDir = "."
217		}
218		if current, err := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); err == nil {
219			if b := strings.TrimSpace(current); b != "" {
220				return b
221			}
222		}
223		return distillDefaultBranch
224	}
