226	func runFactsProposalsList(cmd *cobra.Command, opts Options, pOpts factsProposalsOptions) error {
227		ctx := cmd.Context()
228		target, err := resolveHostedProposalTarget(ctx, opts, pOpts)
229		if err != nil {
230			return err
231		}
232		proposals, err := target.client.ListProposals(ctx, target.repoID, target.branch)
233		// A backend that predates the queue (404/501 on the collection) means no
234		// open proposals can exist there — an answer for `list`, not a transport
235		// failure to dump on the reader (COR-2204).
236		queueUnsupported := errors.Is(err, factsync.ErrProposalQueueUnsupported)
237		if err != nil && !queueUnsupported {
238			return err
239		}
240		if pOpts.jsonOut {
241			if proposals == nil {
242				proposals = []factsync.OpenProposal{}
243			}
244			return writeJSON(cmd, map[string]any{
245				"branch":          target.branch,
246				"repo_id":         target.repoID,
247				"host":            target.baseURL,
248				"open":            len(proposals),
249				"proposals":       proposals,
250				"queue_supported": !queueUnsupported,
251			})
252		}
253		if queueUnsupported {
254			fmt.Fprintf(cmd.OutOrStdout(), "no open cross-member proposals on %s (this server does not serve the proposal queue)\n", target.branch)
255			return nil
256		}
257		out := cmd.OutOrStdout()
258		if len(proposals) == 0 {
259			fmt.Fprintf(out, "no open cross-member proposals on %s\n", target.branch)
260			return nil
261		}
262		fmt.Fprintf(out, "%d open cross-member proposal(s) on %s:\n", len(proposals), target.branch)
263		for _, p := range proposals {
264			fmt.Fprintf(out, "  %s  %s\n", p.ID, describeProposal(p))
265		}
266		fmt.Fprintf(out, "resolve with: memories proposals apply|reject <proposal>\n")
267		return nil
268	}
