270	func runFactsProposalsShow(cmd *cobra.Command, opts Options, pOpts factsProposalsOptions, ref string) error {
271		ctx := cmd.Context()
272		target, err := resolveHostedProposalTarget(ctx, opts, pOpts)
273		if err != nil {
274			return err
275		}
276		// Resolve the caller's reference (id, prefix, or candidate memory id) against the
277		// open set, then fetch the canonical record by its exact id.
278		open, err := target.client.ListProposals(ctx, target.repoID, target.branch)
279		if err != nil {
280			return err
281		}
282		found, err := factsync.FindProposal(open, ref)
283		if err != nil {
284			return err
285		}
286		proposal, err := target.client.GetProposal(ctx, target.repoID, target.branch, found.ID)
287		if err != nil {
288			return err
289		}
290		if pOpts.jsonOut {
291			return writeJSON(cmd, map[string]any{
292				"branch":   target.branch,
293				"repo_id":  target.repoID,
294				"host":     target.baseURL,
295				"proposal": proposal,
296			})
297		}
298		out := cmd.OutOrStdout()
299		fmt.Fprintf(out, "%s\n", proposal.ID)
300		fmt.Fprintf(out, "  branch:     %s\n", target.branch)
301		fmt.Fprintf(out, "  action:     %s\n", proposal.Proposal.Action)
302		fmt.Fprintf(out, "  candidate:  %s\n", proposal.Proposal.CandidateID)
303		fmt.Fprintf(out, "  target:     %s\n", proposal.Proposal.TargetID)
304		fmt.Fprintf(out, "  proposedBy: %s\n", proposalMemberOrUnknown(proposal))
305		fmt.Fprintf(out, "  confidence: %.2f\n", proposal.Proposal.Confidence)
