309	func runFactsProposalsResolve(cmd *cobra.Command, opts Options, pOpts factsProposalsOptions, ref string, decision factsync.Decision) error {
310		ctx := cmd.Context()
311		target, err := resolveHostedProposalTarget(ctx, opts, pOpts)
312		if err != nil {
313			return err
314		}
315		now := opts.Now().UTC()
316		var res factsync.ResolveOpenResult
317		if decision == factsync.Accept {
318			res, err = target.client.ApplyProposal(ctx, target.repoID, target.branch, ref, now)
319		} else {
320			res, err = target.client.RejectProposal(ctx, target.repoID, target.branch, ref, now)
321		}
322		if err != nil {
323			return err
324		}
325		// The hosted set is now the settled truth; drop this member's local
326		// review-queue copy of the same conflict so `facts review`, `facts status`,
327		// and the pending-review guard stop listing a proposal a member just
328		// settled — and so a stale local apply cannot later override this
329		// resolution. Best-effort: the hosted resolution has already succeeded.
330		if pruneErr := pruneLocalProposalCopy(ctx, opts, target.branch, target.repoID, target.baseURL, decision, res.Proposal); pruneErr != nil {
331			fmt.Fprintf(cmd.ErrOrStderr(), "warning: resolved on the hosted queue, but the local review-queue copy was not pruned: %v\n", pruneErr)
332		}
333		if pOpts.jsonOut {
334			return writeJSON(cmd, map[string]any{
335				"branch":   target.branch,
336				"repo_id":  target.repoID,
337				"host":     target.baseURL,
338				"resolved": res,
339			})
340		}
341		out := cmd.OutOrStdout()
342		verb := "applied"
343		detail := "candidate merged/superseded target; the losing memory is retained"
344		if decision == factsync.Reject {
345			verb = "rejected"
346			detail = "both memories stay active; conflict link cleared"
347		}
348		fmt.Fprintf(out, "%s %s on %s (%s)\n", verb, res.Proposal.ID, target.branch, detail)
349		fmt.Fprintf(out, "  memories head: %s (%d attempt(s))\n", refOrNone(res.FactsRef), res.Attempts)
350		fmt.Fprintf(out, "  %d open proposal(s) remain\n", res.Remaining)
351		return nil
352	}
353	
354	// pruneLocalProposalCopy removes the local review-queue copy of a proposal that
355	// was just settled on the hosted queue, AND mirrors the settlement into this
356	// member's local facts. Outside a local repository there is no local queue to
357	// prune, which is success, not an error.
358	//
359	// Mirroring here is what makes the member's own decision visible immediately.
360	// `facts sync` reconciles settlements eventually, but without this the member who
361	// just ran `facts proposals apply` would keep seeing the pre-settlement state in
362	// `facts list`/recall until their next sync — their local view contradicting the
363	// decision they had just made.
364	func pruneLocalProposalCopy(ctx context.Context, opts Options, branch, repoID, baseURL string, decision factsync.Decision, settled factsync.OpenProposal) error {
365		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
366		if err != nil || !local {
367			return err
368		}
369		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
370		if err != nil {
371			return err
372		}
373		// The settled id deliberately STAYS in the shared-proposal ledger: the
374		// ledger records "this conflict has reached the hosted set", and keeping it
375		// suppresses a republish should an identical entry ever re-derive locally.
376		return withBrainWriteLock(storage.BrainDir, func() error {
377			queue, err := loadFactProposals(storage.BrainDir, branch)
378			if err != nil {
379				return err
380			}
381			// Mirror first: a crash between the two writes then leaves the queue entry
382			// in place, and the next sync redoes the (idempotent) mirror rather than
383			// losing it.
384			facts, factsErr := loadFacts(storage.BrainDir, branch)
385			if factsErr != nil {
386				return factsErr
387			}
388			if len(facts) == 0 && len(queue) == 0 {
389				return nil
390			}
391			if err := checkHostedFactsBinding(storage.BrainDir, branch, repoID, baseURL); err != nil {
392				return err
393			}
394			now := opts.Now().UTC()
395			if updated, changed := applySettlementLocally(facts, settled.Proposal, decision == factsync.Accept, now); changed {
396				if err := writeFacts(storage.BrainDir, branch, updated); err != nil {
397					return err
398				}
399				if err := updateFactSourceManifestLocked(storage.BrainDir, now); err != nil {
400					return err
401				}
402			}
403			next := make([]factProposal, 0, len(queue))
404			for _, p := range queue {
405				if factsync.ProposalID(p) == settled.ID {
406					continue
407				}
408				next = append(next, p)
409			}
410			if len(next) == len(queue) {
411				return nil
412			}
413			return writeFactProposals(storage.BrainDir, branch, next)
414		})
415	}
416	
417	// describeProposal renders one open proposal as a single review line.
418	func describeProposal(p factsync.OpenProposal) string {
419		return fmt.Sprintf("%s %s -> %s (by %s, confidence %.2f)",
420			p.Proposal.Action, p.Proposal.CandidateID, p.Proposal.TargetID, proposalMemberOrUnknown(p), p.Proposal.Confidence)
421	}
422	
423	// proposalMemberOrUnknown renders the routing member, tolerating a proposal raised by
424	// an older sync that predates ProposedBy.
425	func proposalMemberOrUnknown(p factsync.OpenProposal) string {
426		if m := strings.TrimSpace(p.Proposal.ProposedBy); m != "" {
427			return m
428		}
429		return "(unknown member)"
430	}
