22	// hostedFake is an in-memory brainstore speaking the per-fact wire:
23	// POST …/brain/facts (identity-verified NDJSON batch, counts reply)
24	// and GET …/brain/facts (insert-ordered keyset feed, index page tokens,
25	// empty page terminal). Upserted records join the feed with the caller's
26	// server-stamped attribution, like the real store.
27	type hostedFake struct {
28		mu           sync.Mutex
29		items        []factsync.FeedItem
30		index        map[string]int
31		requests     int
32		upsertCalls  int
33		feedTokens   []string
34		denyPush     bool // upsert → 403, the push-grant-denied shape
35		denyFeed     bool // feed GET → 500, the pull-outage shape
36		rejectTokens int  // while >0, any request with a pageToken → 400 once each
37		callerBy     string
38		callerHandle string
39	}
40	
41	func (f *hostedFake) requestCount() int {
42		f.mu.Lock()
43		defer f.mu.Unlock()
44		return f.requests
45	}
46	
47	func (f *hostedFake) upsertCount() int {
48		f.mu.Lock()
49		defer f.mu.Unlock()
50		return f.upsertCalls
51	}
52	
53	func (f *hostedFake) feedTokensSeen() []string {
54		f.mu.Lock()
55		defer f.mu.Unlock()
56		return append([]string(nil), f.feedTokens...)
57	}
58	
59	func (f *hostedFake) has(id string) bool {
60		f.mu.Lock()
61		defer f.mu.Unlock()
62		_, ok := f.index[id]
63		return ok
64	}
65	
66	// seed plants a feed item as if another member had upserted it.
67	func (f *hostedFake) seed(rec factmerge.Record, trailID, createdBy, handle string) {
68		f.mu.Lock()
69		defer f.mu.Unlock()
70		f.put(factsync.FeedItem{Record: rec, TrailID: trailID, CreatedBy: createdBy, CreatedByHandle: handle, UpdatedAt: "2026-10-07T12:00:00.000Z"})
71	}
72	
73	// setTrail rewrites a seeded item's trail id in place (simulates the merge
74	// stamp arriving later); feed position is unchanged.
75	func (f *hostedFake) setTrail(id, trailID string) {
76		f.mu.Lock()
77		defer f.mu.Unlock()
78		if i, ok := f.index[id]; ok {
79			f.items[i].TrailID = trailID
80		}
81	}
82	
83	func (f *hostedFake) put(item factsync.FeedItem) {
84		if f.index == nil {
85			f.index = make(map[string]int)
86		}
87		if i, ok := f.index[item.Record.ID]; ok {
88			// Like the real store: a re-upsert updates the record but keeps the
89			// server-owned envelope — first-writer attribution and the trail id
90			// stamped at merge survive later upserts of the same fact — and status
91			// advances one way (a stale active copy never revives a retirement).
92			if f.items[i].Record.Status != factmerge.StatusActive && item.Record.Status == factmerge.StatusActive {
93				item.Record.Status = f.items[i].Record.Status
94				item.Record.SupersededBy = f.items[i].Record.SupersededBy
95			}
96			f.items[i].Record = item.Record
97			return
98		}
99		f.index[item.Record.ID] = len(f.items)
100		f.items = append(f.items, item)
101	}
