103	func newHostedFakeServer(t *testing.T, fake *hostedFake) *httptest.Server {
104		t.Helper()
105		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
106			fake.mu.Lock()
107			defer fake.mu.Unlock()
108			fake.requests++
109			w.Header().Set("Content-Type", "application/json")
110			switch {
111			case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts"):
112				fake.upsertCalls++
113				if fake.denyPush {
114					w.WriteHeader(http.StatusForbidden)
115					return
116				}
117				records, err := factmerge.ParseNDJSON(r.Body)
118				if err != nil || len(records) == 0 || factmerge.VerifyIdentities(records) != nil {
119					w.WriteHeader(http.StatusBadRequest)
120					return
121				}
122				added, changed := 0, 0
123				for _, rec := range records {
124					if _, ok := fake.index[rec.ID]; ok {
125						changed++
126					} else {
127						added++
128					}
129					fake.put(factsync.FeedItem{Record: rec, CreatedBy: fake.callerBy, CreatedByHandle: fake.callerHandle, UpdatedAt: "2026-10-07T12:00:00.000Z"})
130				}
131				_ = json.NewEncoder(w).Encode(map[string]int{"added": added, "changed": changed, "unchanged": 0})
132			case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
133				if fake.denyFeed {
134					w.WriteHeader(http.StatusInternalServerError)
135					return
136				}
137				token := r.URL.Query().Get("pageToken")
138				fake.feedTokens = append(fake.feedTokens, token)
139				if token != "" && fake.rejectTokens > 0 {
140					fake.rejectTokens--
141					w.WriteHeader(http.StatusBadRequest)
142					_, _ = w.Write([]byte(`{"error":"invalid pageToken"}`))
143					return
144				}
145				start := 0
146				if token != "" {
147					n, err := strconv.Atoi(token)
148					if err != nil {
149						w.WriteHeader(http.StatusBadRequest)
150						return
151					}
152					start = n
153				}
154				pageSize, _ := strconv.Atoi(r.URL.Query().Get("pageSize"))
155				if pageSize < 1 || pageSize > 100 {
156					pageSize = 50
157				}
158				end := min(start+pageSize, len(fake.items))
159				var page []factsync.FeedItem
160				if start < end {
161					page = fake.items[start:end]
162				}
163				resp := map[string]any{"items": page, "nextPageToken": nil}
164				if len(page) > 0 {
165					resp["nextPageToken"] = strconv.Itoa(end)
166				}
167				_ = json.NewEncoder(w).Encode(resp)
168			default:
169				w.WriteHeader(http.StatusNotFound)
170			}
171		}))
172		t.Cleanup(srv.Close)
173		return srv
174	}
