// origin; Token is the member's bearer token (same as factsync.HTTPServer). BaseURL
// must clear the shared scheme floor (apiurl.Validate): https, or http only to a
// loopback host.
type Client struct {
	BaseURL string
	Token   string
	HTTP    *http.Client
}

